import { signal } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { AuthPort, SessionState } from '../auth/auth.port';
import { PORTAL_FETCH, RuntimeConfigService, RuntimePublicConfig } from '../auth/runtime-config';
import { BriefEditorStore } from './brief-editor.store';
import { PreferencesComponent } from './preferences.component';
// Generated by services/gcsp-api BriefJavaGoldenTest from the real BriefService and BriefResource.respond; never edited by hand.
import manifest from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/manifest.json';
import editorInitial from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/01-editor-initial.json';
import editorAfterSave from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/03-editor-after-save.json';
import draftSave from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/04-draft-save.json';
import confirmWithConsent from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/05-confirm-with-consent.json';
import editorConfirmed from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/06-editor-confirmed.json';
import editorPaused from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/08-editor-paused.json';
import preferencesStale from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/09-preferences-stale.json';
import editorUnavailable from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/10-editor-unavailable.json';
import preferencesUnavailable from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/11-preferences-unavailable.json';

interface Step {
  readonly file: string; readonly step: string; readonly method: 'GET' | 'POST'; readonly path: string;
  readonly request: Record<string, any> | null; readonly status: number;
  readonly body: { readonly status: string; readonly value?: Record<string, any>; readonly [key: string]: unknown };
}
interface Manifest {
  readonly basePath: string; readonly scope: { readonly environmentId: string; readonly runId: string; readonly employeeId: string; readonly principalId: string; readonly policyVersion: string };
  readonly steps: readonly { readonly step: string }[];
}
const steps: readonly Step[] = [editorInitial, editorAfterSave, draftSave, confirmWithConsent, editorConfirmed, editorPaused, preferencesStale,
  editorUnavailable, preferencesUnavailable].map((s) => structuredClone(s) as unknown as Step);
const index = Object.fromEntries(steps.map((s) => [s.step, s])) as Record<string, Step>;
const plan = manifest as unknown as Manifest;
const value = (name: string): Record<string, any> => structuredClone(index[name].body.value!);
const request = (name: string): Record<string, any> => structuredClone(index[name].request!);
const withoutId = (body: unknown) => { const { commandId: _, ...rest } = body as Record<string, unknown>; return rest; };
const base = `https://api.example${plan.basePath}`;
const TOKEN = 'token-employee';

describe('preferences screen over the Java brief goldens', () => {
  let state: ReturnType<typeof signal<SessionState>>;
  let queue: Map<string, Step[]>;
  let requests: { method: string; path: string; search: string; token: string | null; body: any }[];
  const serve = (...names: string[]) => { for (const name of names) { const s = index[name]; const key = `${s.method} ${s.path}`; queue.set(key, [...(queue.get(key) ?? []), s]); } };
  const sent = (method: string, path: string) => requests.filter((r) => r.method === method && r.path === path);
  const idle = async () => { for (let round = 0; round < 40; round++) { await new Promise<void>((resolve) => setTimeout(resolve, 0)); TestBed.tick(); } };

  beforeEach(() => {
    queue = new Map(); requests = [];
    state = signal<SessionState>({ status: 'signed-out' });
    const config: RuntimePublicConfig = { schemaVersion: 1, environmentId: plan.scope.environmentId, apiBaseUrl: base,
      oidc: { authority: 'https://issuer.example', clientId: 'public-client', scope: 'openid', redirectUri: 'https://portal.example/gcsp/auth/callback', postLogoutRedirectUri: 'https://portal.example/gcsp/' } };
    // Replays only Java-recorded replies; an unrecorded route (the preview) gets a 404 rather than an invented body.
    const fetcher = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = new URL(String(input)); const path = url.pathname.slice(plan.basePath.length);
      const token = new Headers(init?.headers).get('Authorization')?.replace(/^Bearer /, '') ?? null;
      requests.push({ method: init?.method ?? 'GET', path, search: url.search, token, body: init?.body ? JSON.parse(String(init.body)) : undefined });
      if (token !== TOKEN) return new Response(JSON.stringify({ status: 'unauthenticated', code: 'authentication-required' }), { status: 401 });
      const next = queue.get(`${init?.method ?? 'GET'} ${path}`)?.shift();
      if (!next) return new Response(JSON.stringify({ status: 'not-found', code: 'route-not-found' }), { status: 404 });
      return new Response(JSON.stringify(next.body), { status: next.status, headers: { 'Content-Type': 'application/json' } });
    });
    TestBed.configureTestingModule({ providers: [
      { provide: AuthPort, useValue: { state, recovery: signal(null), getAccessToken: async () => (state().status === 'ready' ? TOKEN : null), signIn: vi.fn(), retry: vi.fn() } },
      { provide: RuntimeConfigService, useValue: { load: async () => config } },
      { provide: PORTAL_FETCH, useValue: fetcher }] });
  });
  afterEach(() => vi.restoreAllMocks());

  const signIn = () => state.set({ status: 'ready', context: { subject: plan.scope.principalId, roles: ['employee'], environmentId: plan.scope.environmentId,
    runId: plan.scope.runId, employeeId: plan.scope.employeeId, policyVersion: plan.scope.policyVersion, capabilities: [] } });
  const openStore = async (...names: string[]) => { serve(...names); signIn(); const store = TestBed.inject(BriefEditorStore); TestBed.tick(); await idle(); return store; };
  const render = async (...names: string[]) => { serve(...names); signIn(); const fixture = TestBed.createComponent(PreferencesComponent); await settle(fixture); return fixture; };
  // Waits past the screen's 180 ms preview debounce so its (unrecorded, 404) preview call always lands inside the test.
  const settle = async (fixture: ComponentFixture<PreferencesComponent>) => { await idle(); await new Promise<void>((resolve) => setTimeout(resolve, 200)); await idle(); await fixture.whenStable(); };
  const root = (fixture: ComponentFixture<PreferencesComponent>) => fixture.nativeElement as HTMLElement;
  const button = (fixture: ComponentFixture<PreferencesComponent>, label: string) =>
    [...root(fixture).querySelectorAll('button')].find((b) => b.textContent?.trim() === label) as HTMLButtonElement | undefined;
  const status = (fixture: ComponentFixture<PreferencesComponent>) => root(fixture).querySelector('.brief-form .gcsp-actions + p[role=status]')?.textContent?.trim();
  const note = (fixture: ComponentFixture<PreferencesComponent>) => root(fixture).querySelector(':scope > p.gcsp-note')?.textContent?.trim();
  const ownedRequests = () => {
    expect(requests.length).toBeGreaterThan(0);
    for (const r of requests) {
      expect(r.token).toBe(TOKEN); expect(r.search).toBe(''); expect(r.path).not.toContain(plan.scope.employeeId);
      expect(JSON.stringify(r.body ?? {})).not.toMatch(/"(employeeId|runId|environmentId|principalId|subject)"/);
    }
  };

  it('saveFull sends the Java draft and consent-confirm requests once each and adopts the Java readback', async () => {
    const store = await openStore('editor-after-save', 'draft-save', 'confirm-with-consent', 'editor-confirmed');
    store.updatePreference('body', { value: ['estate'] }); store.updatePreference('economy', { value: 50 }); store.setConsent(true);
    await store.saveFull(); await idle();
    const drafts = sent('POST', '/brief/draft'); const confirms = sent('POST', '/brief/confirm');
    expect(drafts).toHaveLength(1); expect(confirms).toHaveLength(1); expect(sent('POST', '/brief/preferences')).toHaveLength(0);
    // Same versions, brief and consent as the requests Java answered; only the generated commandId differs.
    expect(drafts[0].body.commandId).toMatch(/^draft:/); expect(withoutId(drafts[0].body)).toEqual(withoutId(request('draft-save')));
    expect(confirms[0].body.commandId).toMatch(/^confirm:/); expect(withoutId(confirms[0].body)).toEqual(withoutId(request('confirm-with-consent')));
    expect(sent('GET', '/brief/editor')).toHaveLength(2);
    const readback = value('editor-confirmed')['initial'];
    expect(store.briefVersion()).toBe(readback['briefVersion']); expect(store.draftVersion()).toBe(readback['draftVersion']);
    expect(value('confirm-with-consent')['brief']['briefVersion']).toBe(readback['briefVersion']);
    expect(store.brief()).toEqual(readback['brief']); expect(store.consent()).toEqual(readback['consent']);
    expect(store.editor()?.initial.buddy).toEqual(readback['buddy']); expect(store.editor()?.initial.buddy.state).toBe('engaged');
    expect(store.fullState()).toBe('saved'); expect(store.failure()).toBeNull();
    expect(store.message()).toBe(`Your preferences were confirmed. Showing saved version ${readback['briefVersion']}.`);
    ownedRequests();
  });

  it('renders the Java initial editor: known facts, preferences, version and Buddy choice, and no match of its own', async () => {
    const fixture = await render('editor-initial');
    const java = value('editor-initial');
    const facts = [...root(fixture).querySelectorAll('.known-facts dt')].map((dt) => [dt.textContent?.trim(), dt.nextElementSibling?.textContent?.trim()]);
    expect(facts).toEqual([['Current car', 'Model X'], ['Contract ends', 'Not supplied'], ['Drivers', 'Pat'], ['Annual mileage', '8000 miles']]);
    expect(java['context']['knownFacts']['currentContract']['value']['model']).toBe('Model X');
    expect(note(fixture)).toBe(`Your saved preferences · Version ${java['initial']['briefVersion']}`);
    const legends = [...root(fixture).querySelectorAll('fieldset.full-preference legend')].map((l) => l.textContent?.trim());
    expect(legends).toEqual(Object.values(java['context']['preferences']).map((p: any) => p.label));
    const body = java['context']['preferences']['body']['values'] as string[];
    const boxes = [...root(fixture).querySelectorAll<HTMLInputElement>('#preference-body input')];
    expect(boxes.map((b) => b.checked)).toEqual(body.map((v) => v === java['initial']['brief']['preferences']['body']['value']));
    const [engage, disengage] = [...root(fixture).querySelectorAll<HTMLInputElement>('input[name=buddy-engagement]')];
    expect(java['initial']['buddy']['state']).toBe('disengaged'); expect(engage.checked).toBe(false); expect(disengage.checked).toBe(true);
    expect(root(fixture).textContent).not.toMatch(/\bEligible\b|Not eligible/);
    ownedRequests();
  });

  it('a full save from the screen controls sends the Java requests and shows the server saved version', async () => {
    const fixture = await render('editor-after-save', 'draft-save', 'confirm-with-consent', 'editor-confirmed');
    const values = value('editor-after-save')['context']['preferences']['body']['values'] as string[];
    const estate = root(fixture).querySelectorAll<HTMLInputElement>('#preference-body input')[values.indexOf('estate')];
    estate.checked = true; estate.dispatchEvent(new Event('change'));
    const economy = root(fixture).querySelector<HTMLInputElement>('#preference-economy')!;
    economy.value = '50'; economy.dispatchEvent(new Event('input'));
    const engage = root(fixture).querySelector<HTMLInputElement>('input[name=buddy-engagement]')!;
    engage.checked = true; engage.dispatchEvent(new Event('change'));
    await settle(fixture);
    expect(note(fixture)).toBe('Unsaved draft · Version 0'); expect(button(fixture, 'Save your preferences')?.disabled).toBe(false);
    root(fixture).querySelector('form.brief-form')!.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
    await settle(fixture);
    expect(sent('POST', '/brief/draft')).toHaveLength(1); expect(sent('POST', '/brief/confirm')).toHaveLength(1);
    expect(withoutId(sent('POST', '/brief/draft')[0].body)).toEqual(withoutId(request('draft-save')));
    expect(withoutId(sent('POST', '/brief/confirm')[0].body)).toEqual(withoutId(request('confirm-with-consent')));
    const readback = value('editor-confirmed')['initial'];
    expect(status(fixture)).toBe(`Your preferences were confirmed. Showing saved version ${readback['briefVersion']}.`);
    expect(note(fixture)).toBe(`Your saved preferences · Version ${readback['briefVersion']}`);
    expect(root(fixture).querySelector<HTMLInputElement>('input[name=buddy-engagement]')!.checked).toBe(true);
    expect(root(fixture).textContent).not.toMatch(/\bEligible\b|Not eligible/);
    ownedRequests();
  });

  it('a stale save shows the truthful message, blocks retry and saving, and the reload correction shows the newer Java state', async () => {
    // Java recorded the pause between the confirmed read and the stale write, so this tab is one brief version behind.
    const order = plan.steps.map((s) => s.step);
    expect(order.indexOf('editor-confirmed')).toBeLessThan(order.indexOf('pause-search'));
    expect(order.indexOf('pause-search')).toBeLessThan(order.indexOf('preferences-stale'));
    const fixture = await render('editor-confirmed', 'preferences-stale', 'editor-paused');
    fixture.componentInstance.store.change('size', { value: 100 }); await settle(fixture);
    const write = sent('POST', '/brief/preferences'); const java = request('preferences-stale');
    expect(write).toHaveLength(1);
    expect(write[0].body).toMatchObject({ expectedBriefVersion: java['expectedBriefVersion'], expectedDraftVersion: java['expectedDraftVersion'] });
    // The store also names the fresh category's importance; Java's stale refusal is decided on versions before content.
    expect(write[0].body.changes).toEqual({ size: { ...java['changes']['size'], importance: 'medium' } });
    expect(status(fixture)).toBe('Your preferences changed elsewhere. Reload to see the latest. Your edits are kept until then.');
    expect(fixture.componentInstance.store.category('size')).toMatchObject({ state: 'considered', value: 100 });
    expect(button(fixture, 'Try again')).toBeUndefined(); expect(button(fixture, 'Save your preferences')?.disabled).toBe(true);
    button(fixture, 'Refresh and review')!.click(); await settle(fixture);
    button(fixture, 'Replace draft with saved preferences')!.click(); await settle(fixture);
    const paused = value('editor-paused');
    expect(sent('GET', '/brief/editor')).toHaveLength(2); expect(sent('POST', '/brief/preferences')).toHaveLength(1);
    expect(fixture.componentInstance.store.failure()).toBeNull(); expect(status(fixture)).toBe('');
    expect(note(fixture)).toBe(`Your saved preferences · Version ${paused['initial']['briefVersion']}`);
    expect(fixture.componentInstance.store.categories()).toEqual(paused['initial']['accountPreferences']['categories']);
    expect(fixture.componentInstance.store.editor()?.initial.buddy).toEqual(paused['initial']['buddy']);
    ownedRequests();
  });

  it('an unavailable save keeps the edit, says it is not confirmed and offers Try again', async () => {
    const fixture = await render('editor-paused', 'preferences-unavailable');
    fixture.componentInstance.store.change('size', { value: 100 }); await settle(fixture);
    const write = sent('POST', '/brief/preferences'); const java = request('preferences-unavailable');
    expect(write).toHaveLength(1);
    expect(write[0].body).toMatchObject({ expectedBriefVersion: java['expectedBriefVersion'], expectedDraftVersion: java['expectedDraftVersion'] });
    expect(status(fixture)).toBe('Your changes are not confirmed as saved. Try again or reload.');
    expect(button(fixture, 'Try again')).toBeDefined();
    expect(fixture.componentInstance.store.category('size')).toMatchObject({ state: 'considered', value: 100 });
    expect(fixture.componentInstance.store.draftVersion()).toBe(value('editor-paused')['initial']['draftVersion']);
    expect(note(fixture)).toBe(`Your saved preferences · Version ${value('editor-paused')['initial']['briefVersion']}`);
    ownedRequests();
  });

  it('an unavailable editor read shows the truthful status screen, and Try again reads again without inventing state', async () => {
    const fixture = await render('editor-unavailable', 'editor-unavailable');
    expect(index['editor-unavailable'].status).toBe(503);
    expect(root(fixture).textContent).toContain('Your preferences could not be loaded. Try again.');
    expect(root(fixture).querySelector('.known-facts')).toBeNull(); expect(root(fixture).querySelector('form.brief-form')).toBeNull();
    button(fixture, 'Try again')!.click(); await settle(fixture);
    expect(sent('GET', '/brief/editor')).toHaveLength(2); expect(fixture.componentInstance.store.editor()).toBeNull();
    expect(root(fixture).textContent).toContain('Your preferences could not be loaded. Try again.');
    expect(root(fixture).textContent).not.toMatch(/\bEligible\b|Not eligible|Model X/);
    ownedRequests();
  });
});
